type ServerErrorData = Omit<HttpStatus, 'category' | 'categoryRange' | 'categoryLabel' | 'media' | 'mediaType'> & {
  mediaUrl: string
}

const serverError = ({ mediaUrl, ...data }: ServerErrorData): HttpStatus => ({
  ...data,
  category: 'Server Error',
  categoryRange: '5xx',
  categoryLabel: 'Erro do servidor',
  media: { preview: mediaUrl, full: mediaUrl },
  mediaType: 'gif',
})

